-- HISTORIA (11 questoes)
DO $$
DECLARE mid uuid; aid uuid;
BEGIN
  SELECT id INTO mid FROM public.materias WHERE nome = 'Historia' LIMIT 1;
  SELECT id INTO aid FROM public.treineiro_aulas WHERE materia_id = mid LIMIT 1;
  IF mid IS NOT NULL AND aid IS NOT NULL THEN
  END IF;
END$$;

